// Alerts after two failed checks in a row (a single blip is ignored),
// repeats hourly while down, and reports recovery with the downtime.
const s = $getWorkflowStaticData('global');
const probe = (name) => {
  const r = $(name).first().json || {};
  const code = Number(r.statusCode) || 0;
  const ok = code >= 200 && code < 400;
  const why = code ? 'HTTP ' + code : (r.error?.message || r.message || 'no response');
  return { name, ok, why };
};
const results = [probe('Homepage'), probe('Prices API')];
const failed = results.filter((r) => !r.ok);
const now = Date.now();
const stamp = new Date(now).toLocaleString('en-IN', { timeZone: 'Asia/Kolkata', hour: '2-digit', minute: '2-digit', day: 'numeric', month: 'short' });
if (failed.length) {
  s.fails = (s.fails || 0) + 1;
  if (!s.down && s.fails >= 2) {
    s.down = true; s.downSince = now - 5 * 60000; s.lastAlert = now;
    return [{ json: { text: 'SITE DOWN: paisareality.com\n' + failed.map((f) => f.name + ': ' + f.why).join('\n') + '\nTwo checks failed in a row, at ' + stamp + ' IST.' } }];
  }
  if (s.down && now - (s.lastAlert || 0) >= 60 * 60000) {
    s.lastAlert = now;
    const mins = Math.round((now - s.downSince) / 60000);
    return [{ json: { text: 'Still down after ' + mins + ' minutes: paisareality.com\n' + failed.map((f) => f.name + ': ' + f.why).join('\n') } }];
  }
  return [];
}
s.fails = 0;
if (s.down) {
  const mins = Math.round((now - s.downSince) / 60000);
  s.down = false;
  return [{ json: { text: 'Back up: paisareality.com is answering again (' + stamp + ' IST). Down for about ' + mins + ' minutes.' } }];
}
return [];
